    // ══════════════════════════════════════════════════════════════
    // PIPELINE MONITOR (FILM-069)
    // ══════════════════════════════════════════════════════════════
    async function loadPipeline() {
        if (!state.currentProject) return;
        setStatus('Loading pipeline...');
        try {
            // Load recent renders across all shots + consistency readiness.
            const [sbData, auditD] = await Promise.all([
                api('/projects/' + state.currentProject.id + '/status-board'),
                api('/projects/' + state.currentProject.id + '/consistency/audit').catch(() => ({ ready: true, shots: [] })),
            ]);
            const allShots = [];
            (sbData.scenes || []).forEach(s => (s.shots || []).forEach(sh => allShots.push({ ...sh, scene_number: s.scene_number, scene_id: s.id })));
            // shot_id -> readiness (from the same gate the pipeline enforces).
            const readyByShot = {};
            (auditD.shots || []).forEach(s => { readyByShot[s.shot_id] = s; });
            renderPipelineReadiness(auditD);

            // Show active (generating) shots
            const active = allShots.filter(s => s.status === 'generating');
            const activeEl = document.getElementById('pipelineActive');
            if (active.length === 0) {
                activeEl.innerHTML = '<div class="card"><p class="text-sm text-muted">No active pipeline runs.</p></div>';
            } else {
                activeEl.innerHTML = '<h3 class="mb-8">Active Runs</h3>' + active.map(s => `
                    <div class="card mb-8">
                        <div class="flex-between">
                            <strong>Sc${s.scene_number} / ${esc(s.shot_code)}</strong>
                            <span class="badge">generating</span>
                        </div>
                        <div style="background:var(--gl-border-subtle);border-radius:4px;height:4px;margin-top:8px;">
                            <div style="background:var(--gl-brand-pink);height:100%;width:50%;border-radius:4px;"></div>
                        </div>
                    </div>`).join('');
            }

            // Show history table of completed/pending
            const histEl = document.getElementById('pipelineHistory');
            const others = allShots.filter(s => s.status !== 'generating');
            if (others.length === 0) {
                histEl.innerHTML = '<p class="text-sm text-muted">No pipeline history yet.</p>';
            } else {
                histEl.innerHTML = `<table class="render-table">
                    <tr><th>Shot</th><th>Scene</th><th>Status</th><th>Duration</th></tr>
                    ${others.map(s => `<tr>
                        <td>${esc(s.shot_code)}</td>
                        <td>Sc${s.scene_number}</td>
                        <td><span class="badge ${s.status === 'approved' ? 'approved' : ''}">${esc(s.status)}</span></td>
                        <td>${s.duration_ms ? (s.duration_ms/1000).toFixed(1) + 's' : '-'}</td>
                    </tr>`).join('')}
                </table>`;
            }
            // Populate the run-scope shot selector.
            const sel = document.getElementById('pipelineShotSelect');
            if (sel) {
                sel.innerHTML = allShots.length
                    ? allShots.map(s => {
                        const r = readyByShot[s.id];
                        const mark = r && r.ready === false ? '⚠ ' : '';
                        return `<option value="${esc(s.id)}" data-scene="${esc(s.scene_id || '')}" data-ready="${r ? (r.ready ? '1' : '0') : ''}">${mark}Sc${s.scene_number} / ${esc(s.shot_code)}</option>`;
                    }).join('')
                    : '<option value="">No shots — create shots first</option>';
            }
            // Show the providers each step will use (from per-project config).
            try {
                const prov = await api('/projects/' + state.currentProject.id + '/providers');
                const e = prov.effective || {};
                const provLine = document.getElementById('pipelineProviders');
                if (provLine) provLine.innerHTML = 'Providers → LLM: <strong>' + esc(e.llm || 'gridlight') + '</strong>, image: <strong>' + esc(e.image || 'gridlight') + '</strong>, video: <strong>' + esc(e.video || 'gridlight') + '</strong>, voice: <strong>' + esc(e.voice || 'gridlight') + '</strong>, music: <strong>' + esc(e.music || 'gridlight') + '</strong> · <a style="cursor:pointer;color:var(--gl-accent,#818cf8);" onclick="navigateTo(\'settings\')">change</a>';
            } catch (_) {}

            setStatus(allShots.length + ' shot(s) in pipeline');
        } catch (err) { setStatus('Error: ' + err.message); }
    }

    // Surface consistency readiness on the Pipeline page — the same gate the
    // backend enforces (strict mode blocks a run whose in-frame subjects aren't
    // locked). Shows what's blocking BEFORE a run is started.
    function renderPipelineReadiness(audit) {
        const el = document.getElementById('pipelineReadiness');
        if (!el) return;
        const shots = (audit && audit.shots) || [];
        if (!shots.length) { el.innerHTML = ''; return; }
        const ready = shots.filter(s => s.ready).length;
        const blocked = shots.filter(s => !s.ready);
        const allReady = blocked.length === 0;
        const color = allReady ? 'var(--gl-success,#22c55e)' : 'var(--gl-warning,#f59e0b)';
        let html = `<div class="card" style="border-left:4px solid ${color};padding:8px 12px;">
            <strong>${allReady ? '✓ Consistency ready' : '⚠ ' + blocked.length + ' shot(s) not locked'}</strong>
            <span class="text-sm text-muted"> — ${ready}/${shots.length} shots ready.${allReady ? '' : ' Strict mode will block these.'}</span>`;
        if (blocked.length) {
            html += '<div class="text-sm text-muted" style="margin-top:6px;">' + blocked.slice(0, 6).map(s =>
                esc(s.shot_code || (s.shot_id || '').slice(0, 8)) + ': ' + esc((s.missing || []).join('; ') || 'not ready')
            ).join('<br>') + (blocked.length > 6 ? '<br>…and ' + (blocked.length - 6) + ' more' : '') + '</div>';
        }
        html += '</div>';
        el.innerHTML = html;
    }

    // ── Live pipeline run (scene → final) ───────────────────────────
    const PIPE_STEP_ICONS = { pending: '&#9675;', running: '&#9679;', complete: '&#10003;', failed: '&#10007;' };
    function renderPipelineSteps(steps, stateMap) {
        return '<div style="display:flex;flex-direction:column;gap:4px;">' + steps.map(st => {
            const s = stateMap[st.id] || 'pending';
            const color = s === 'complete' ? 'var(--gl-success,#22c55e)' : s === 'failed' ? 'var(--gl-danger,#ef4444)' : s === 'running' ? 'var(--gl-accent,#818cf8)' : 'var(--gl-text-muted)';
            return `<div style="display:flex;align-items:center;gap:8px;font-size:13px;">
                <span style="color:${color};width:16px;text-align:center;">${PIPE_STEP_ICONS[s] || '&#9675;'}</span>
                <span style="color:${s === 'pending' ? 'var(--gl-text-muted)' : 'var(--gl-text-primary)'};">${esc(st.name || st.id)}</span>
                ${s === 'running' ? '<span class="text-sm text-muted">…</span>' : ''}
            </div>`;
        }).join('') + '</div>';
    }

    function runPipelineLive() {
        const sel = document.getElementById('pipelineShotSelect');
        const shotId = sel && sel.value;
        if (!shotId) { setStatus('Pick a shot first'); return; }
        const label = sel.options[sel.selectedIndex].textContent;
        const strict = !!(document.getElementById('pipelineStrict') || {}).checked;
        const live = document.getElementById('pipelineLive');
        // Pre-flight: give instant feedback if strict mode will block this shot
        // (the backend re-checks authoritatively when the run starts).
        const selReady = sel.options[sel.selectedIndex].getAttribute('data-ready');
        if (strict && selReady === '0') {
            live.innerHTML = '<div class="card" style="border-left:4px solid var(--gl-danger,#ef4444);padding:8px 12px;"><strong>⛔ Strict consistency: shot not locked</strong><div class="text-sm text-muted" style="margin-top:4px;">Lock its in-frame subjects in the Consistency Studio, or uncheck Strict consistency to run anyway.</div></div>';
            setStatus('Blocked by strict consistency');
            return;
        }
        let steps = [];
        const stateMap = {};
        live.innerHTML = '<div class="text-sm text-muted">Starting ' + esc(label) + '…</div>';

        streamSSEPost('/shots/' + shotId + '/pipeline/run/stream', { strict },
            (ev) => {
                if (ev.type === 'readiness') {
                    const bad = [...(ev.missing || []), ...(ev.warnings || [])];
                    if (!ev.ready || bad.length) {
                        const c = ev.ready ? 'var(--gl-warning,#f59e0b)' : 'var(--gl-danger,#ef4444)';
                        live.innerHTML = '<div class="card" style="border-left:4px solid ' + c + ';padding:8px 12px;margin-bottom:8px;"><strong>' + (ev.ready ? '⚠ Consistency warnings' : '⛔ Consistency not ready') + '</strong><div class="text-sm text-muted" style="margin-top:4px;">' + bad.map(esc).join('<br>') + '</div></div>' + '<div class="text-sm text-muted">Running ' + esc(label) + '…</div>';
                    }
                } else if (ev.type === 'status' && Array.isArray(ev.steps)) {
                    steps = ev.steps;
                    steps.forEach(st => stateMap[st.id] = 'pending');
                    live.innerHTML = '<strong style="font-size:13px;">' + esc(label) + '</strong>' + renderPipelineSteps(steps, stateMap);
                } else if (ev.type === 'step_start') {
                    stateMap[ev.step_id] = 'running';
                    live.innerHTML = '<strong style="font-size:13px;">' + esc(label) + '</strong>' + renderPipelineSteps(steps, stateMap);
                } else if (ev.type === 'step_complete') {
                    stateMap[ev.step_id] = 'complete';
                    live.innerHTML = '<strong style="font-size:13px;">' + esc(label) + '</strong>' + renderPipelineSteps(steps, stateMap);
                } else if (ev.type === 'step_failed') {
                    stateMap[ev.step_id] = 'failed';
                    live.innerHTML = '<strong style="font-size:13px;">' + esc(label) + '</strong>' + renderPipelineSteps(steps, stateMap);
                } else if (ev.type === 'cancelled') {
                    live.innerHTML += '<div class="text-sm text-muted" style="margin-top:6px;">Cancelled.</div>';
                }
            },
            (done) => {
                const failed = steps.filter(st => stateMap[st.id] === 'failed').length;
                live.innerHTML += '<div style="margin-top:8px;color:' + (failed ? 'var(--gl-danger,#ef4444)' : 'var(--gl-success,#22c55e)') + ';font-size:13px;">' + (failed ? failed + ' step(s) failed' : 'Pipeline complete →  ready to assemble / Export') + '</div>';
                setStatus('Pipeline finished');
                loadPipeline();
            },
            (err) => { live.innerHTML += '<div class="text-sm" style="color:var(--gl-danger,#ef4444);margin-top:6px;">Error: ' + esc(err ? err.message : 'stream failed') + '</div>'; }
        );
    }

    async function runPipelineScope(scope) {
        const sel = document.getElementById('pipelineShotSelect');
        const opt = sel && sel.options[sel.selectedIndex];
        const strict = !!(document.getElementById('pipelineStrict') || {}).checked;
        const body = JSON.stringify({ strict });
        try {
            if (scope === 'scene') {
                const sceneId = opt && opt.getAttribute('data-scene');
                if (!sceneId) { setStatus('Pick a shot to identify its scene'); return; }
                setStatus('Running scene pipeline…');
                await api('/scenes/' + sceneId + '/pipeline/run', { method: 'POST', body });
            } else {
                setStatus('Running project pipeline…');
                await api('/projects/' + state.currentProject.id + '/pipeline/run', { method: 'POST', body });
            }
            setStatus(scope + ' pipeline complete');
            loadPipeline();
        } catch (err) { setStatus('Error: ' + err.message); }
    }
